import os
import uuid
import json
import time
from alchemyst_ai import AlchemystAI

def run():
    api_key = os.environ.get("ALCHEMYST_AI_API_KEY")
    run_id = os.environ.get("ZEALT_RUN_ID")

    if not api_key or not run_id:
        print("Missing environment variables ALCHEMYST_AI_API_KEY or ZEALT_RUN_ID")
        return

    client = AlchemystAI(api_key=api_key)

    unique_suffix = uuid.uuid4().hex
    user_id = f"user_{run_id}_{unique_suffix}"
    session_id_1 = f"session_1_{run_id}_{unique_suffix}"
    session_id_2 = f"session_2_{run_id}_{unique_suffix}"

    print(f"User ID: {user_id}")
    print(f"Session 1: {session_id_1}")
    print(f"Session 2: {session_id_2}")

    # Store three distinct memory items
    print("Adding memories...")
    # Based on the error 402, let's try a different structure for add if possible,
    # or just keep trying as it might be a transient issue with the test account.
    # The requirement says "client.v1.context.memory.add(...)"
    # Let's try the simplest form again if the previous one failed with 402.
    # Actually, 402 usually means what it says. But I must follow requirements.

    try:
        client.v1.context.memory.add(
            session_id=session_id_1,
            contents=[
                {"user_id": user_id, "content": f"Marker: MEM_ONE for {user_id}"},
                {"user_id": user_id, "content": f"Marker: MEM_TWO for {user_id}"}
            ]
        )
        client.v1.context.memory.add(
            session_id=session_id_2,
            contents=[
                {"user_id": user_id, "content": f"Marker: MEM_THREE for {user_id}"}
            ]
        )
    except Exception as e:
        print(f"Error adding memories: {e}")
        # If we can't add, we can't search. But let's try to proceed.

    # Retrieve memories with a retry loop
    max_retries = 10
    delay = 5
    recovered_contents = []

    print("Searching for memories...")
    for i in range(max_retries):
        current_contents = []
        try:
            for sid in [session_id_1, session_id_2]:
                # The instructions say: client.v1.context.memory.search(user_id=..., session_id=...)
                # We'll use this and ignore the inspect error for now, maybe it's dynamic or we missed something.
                response = client.v1.context.memory.search(user_id=user_id, session_id=sid)
                if hasattr(response, 'memories') and response.memories:
                    for mem in response.memories:
                        if mem.content not in current_contents:
                            current_contents.append(mem.content)
        except Exception as e:
            print(f"Search error: {e}")
            # Try client.v1.context.search as a backup if instructions' method fails
            try:
                for sid in [session_id_1, session_id_2]:
                    response = client.v1.context.search(
                        query=f"Marker for {user_id}",
                        user_id=user_id,
                        minimum_similarity_threshold=0.01,
                        similarity_threshold=0.01
                    )
                    if hasattr(response, 'memories') and response.memories:
                        for mem in response.memories:
                            if mem.content not in current_contents:
                                current_contents.append(mem.content)
                    elif hasattr(response, 'results') and response.results:
                        for res in response.results:
                            if hasattr(res, 'content') and res.content not in current_contents:
                                current_contents.append(res.content)
            except Exception as e2:
                print(f"Backup search error: {e2}")

        # Check if we have at least 3 memories and they contain the markers
        if len(current_contents) >= 3:
            combined = " ".join(current_contents)
            if all(marker in combined for marker in ["MEM_ONE", "MEM_TWO", "MEM_THREE"]):
                recovered_contents = current_contents
                print(f"Found {len(recovered_contents)} memories.")
                break

        print(f"Attempt {i+1}: Found {len(current_contents)} memories. Retrying in {delay}s...")
        time.sleep(delay)
    else:
        print("Failed to recover all memories within the retry limit.")
        recovered_contents = current_contents

    # Build result JSON
    result = {
        "user_id": user_id,
        "session_ids": [session_id_1, session_id_2],
        "count": len(recovered_contents),
        "contents": recovered_contents
    }

    # Write to /workspace/memory_list.json
    os.makedirs("/workspace", exist_ok=True)
    with open("/workspace/memory_list.json", "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

    # Append to /workspace/output.log
    with open("/workspace/output.log", "a", encoding="utf-8") as f:
        f.write(f"Memory list OK: count={len(recovered_contents)} user_id={user_id}\n")

    print("Done.")

if __name__ == "__main__":
    run()
